export function getRecall(topicId: string, bookId: string, partId: string): RecallQ[] {
  return RECALL[`${topicId}/${bookId}/${partId}`] ?? [];
}

export function getMcqPool(topicId: string, bookId: string, partId: string): MCQ[] {
  return MCQS[`${topicId}/${bookId}/${partId}`] ?? [];
}

// All MCQs across every playable part/book of a topic, combined for an
// exam-style session. IDs are re-numbered so questions from different parts
// (which each start at id 1) stay unique for React keys and answer tracking.
export function getTopicMcqPool(topicId: string): MCQ[] {
  const prefix = `${topicId}/`;
  return Object.entries(MCQS)
    .filter(([key]) => key.startsWith(prefix))
    .flatMap(([, questions]) => questions)
    .map((q, i) => ({ ...q, id: i + 1 }));
}

// All recall cards across every part of a single book, combined into one deck
// (chapters are merged so a book reads as a single recall session). IDs are
// renumbered so cards from different parts stay unique for React keys.
export function getBookRecall(topicId: string, bookId: string): RecallQ[] {
  const prefix = `${topicId}/${bookId}/`;
  return Object.entries(RECALL)
    .filter(([key]) => key.startsWith(prefix))
    .flatMap(([, questions]) => questions)
    .map((q, i) => ({ ...q, id: i + 1 }));
}

// All MCQs across every part of a single book, combined into one exam pool.
export function getBookMcqPool(topicId: string, bookId: string): MCQ[] {
  const prefix = `${topicId}/${bookId}/`;
  return Object.entries(MCQS)
    .filter(([key]) => key.startsWith(prefix))
    .flatMap(([, questions]) => questions)
    .map((q, i) => ({ ...q, id: i + 1 }));
}
